import unittest
from receipt import total
class Contract(unittest.TestCase):
    def test_total(self): self.assertEqual(total([10, 20]), 30)
    def test_empty(self): self.assertEqual(total([]), 0)

    def test_fractional_discount(self):
        self.assertEqual(total([10, 20], discount=0.25), 22.5)

    def test_discount_boundaries(self):
        self.assertEqual(total([10, 20], discount=0), 30)
        self.assertEqual(total([10, 20], discount=1), 0)

    def test_positional_discount(self):
        self.assertEqual(total([10, 20], 0.5), 15)

    def test_empty_with_discount(self):
        for discount in (0, 0.25, 1):
            with self.subTest(discount=discount):
                self.assertEqual(total([], discount=discount), 0)

    def test_invalid_discount(self):
        for discount in (-0.01, 1.01, float("nan"), float("-inf"), float("inf")):
            with self.subTest(discount=discount):
                with self.assertRaises(ValueError):
                    total([10, 20], discount=discount)

    def test_invalid_discount_with_empty_receipt(self):
        with self.assertRaises(ValueError):
            total([], discount=-0.01)

    def test_iterable_prices(self):
        self.assertEqual(total(iter([10, 20]), discount=0.25), 22.5)

