import unittest
from calc import multiply
class Contract(unittest.TestCase):
    def test_product(self):
        self.assertEqual(multiply(2, 3), 6)

    def test_zero(self):
        self.assertEqual(multiply(0, 7), 0)
        self.assertEqual(multiply(7, 0), 0)

    def test_identity(self):
        self.assertEqual(multiply(1, 7), 7)
        self.assertEqual(multiply(7, 1), 7)

    def test_negative_operands(self):
        self.assertEqual(multiply(-2, 3), -6)
        self.assertEqual(multiply(2, -3), -6)
        self.assertEqual(multiply(-2, -3), 6)

    def test_fractional_operands(self):
        self.assertEqual(multiply(1.5, 2.0), 3.0)

    def test_large_integers(self):
        self.assertEqual(multiply(18446744073709551616, 3), 55340232221128654848)

    def test_infinite_product(self):
        self.assertEqual(multiply(float("inf"), 2), float("inf"))

    def test_unsupported_operands(self):
        with self.assertRaises(TypeError):
            multiply({}, 2)

